// Flattens BriefGate's get_intake_results 'results' object into one item
// per file/image found, so each can be downloaded and uploaded on its own.
const results = $input.first().json.results ?? {};
const items = [];

for (const [key, value] of Object.entries(results)) {
  if (value && typeof value === 'object' && typeof value.url === 'string') {
    // file / image item
    items.push({ json: { key, url: value.url, filename: value.filename || key } });
  } else if (Array.isArray(value)) {
    // file_list item
    for (const entry of value) {
      if (entry && typeof entry === 'object' && typeof entry.url === 'string') {
        items.push({ json: { key, url: entry.url, filename: entry.filename || key } });
      }
    }
  }
}

return items;

